	it("answers a trigger, posts once, and pushes the thread to the remote", async () => {
		const w = world();
		w.faux.setResponses([fauxAssistantMessage("Fixed it.")]);
		const trigger = w.comment("@pi please fix");

		await run(w.deps(trigger));

		expect(w.gh.posted).toHaveLength(1);
		expect(w.gh.posted[0]).toContain("### 🤖 pi Response\n\nFixed it.");
		expect(w.gh.posted[0]).toContain(REF);
		expect(w.reacted("eyes")).toStrictEqual([trigger.id]);
		expect(w.reacted("rocket")).toStrictEqual([trigger.id]);
		const log = git(w.remote, "log", "--format=%s", REF);
		expect(log).toMatch(FIRST_COMMIT);
	});

	it("applies model_tools_hidden on each run, and clears it when the input is empty", async () => {
		const w = world();
		const seen: string[][] = [];
		const record: FauxResponseStep = (context) => {
			seen.push(toolsOf(context).map((tool) => tool.name));
			return fauxAssistantMessage("ok");
		};
		w.faux.setResponses([record, record]);

		const hidden = w.deps(w.comment("@pi one"), { modelToolsHidden: ["bash"] });
		await run(hidden);
		await run(w.deps(w.comment("@pi two")));

		expect(seen).toStrictEqual([
			["read", "write", "edit"],
			["read", "write", "edit", "bash"],
		]);
		expect(hidden.log.info).toHaveBeenCalledWith(
			expect.stringMatching(/ · tools: read, write, edit$/u),
		);
	});

	it("loads .pi/prompts with trust_project only, before agent_dir/prompts, also for follow-ups", async () => {
	it("saves nothing with worktree_snapshots: false", async () => {
		const w = world();
		w.faux.setResponses([
			fauxAssistantMessage(
				[fauxToolCall("bash", { command: "echo x > x.txt" })],
				{
					stopReason: "toolUse",
				},
			),
			fauxAssistantMessage("done"),
		]);
		await run(w.deps(w.comment("@pi go"), { worktreeSnapshots: false }));
		expect(git(w.remote, "ls-remote", w.remote, "refs/pi/*")).not.toContain(
			WORKTREES,
		);
		expect(git(w.remote, "ls-remote", w.remote, "refs/pi/*")).toContain(REF);
	});
});
